package io.eip.ingestion;

import static org.junit.jupiter.api.Assertions.*;
import com.fasterxml.jackson.databind.ObjectMapper;
import io.eip.activity.*;
import io.eip.common.*;
import io.eip.project.*;
import io.eip.security.*;
import java.time.Instant;import java.util.*;import java.util.concurrent.*;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;
@SpringBootTest
class IngestionServiceTest {
 @Autowired ProjectService projects;@Autowired ActivityService activities;@Autowired ServiceIdentityService identities;@Autowired IngestionService ingestion;@Autowired IngestedEvidenceRepository evidences;@Autowired ObjectMapper json;
 @Test void ingestsWithScopeAndMakesDeclaredActivityAssociation() throws Exception { Fixture f=fixture(); IngestionService.Result first=ingestion.ingest("Bearer "+f.token,"key-"+UUID.randomUUID(),request(f,"event-"+UUID.randomUUID(),f.activity));assertFalse(first.duplicate()); IngestionService.Result replay=ingestion.ingest("Bearer "+f.token,"same-key",request(f,"event-replay",f.activity));assertFalse(replay.duplicate());assertTrue(ingestion.ingest("Bearer "+f.token,"same-key",request(f,"event-replay",f.activity)).duplicate()); }
 @Test void rejectsInvalidRevokedSuspendedAndUnauthorizedAccess() throws Exception { Fixture f=fixture(); assertThrows(UnauthorizedException.class,()->ingestion.ingest("Bearer eip_si_"+UUID.randomUUID()+".wrong","k1",request(f,"bad1",null))); identities.revoke(f.org,f.project,f.identity,f.credential,"admin");assertThrows(UnauthorizedException.class,()->ingestion.ingest("Bearer "+f.token,"k2",request(f,"bad2",null))); Fixture active=fixture(); identities.setSuspended(active.org,active.project,active.identity,true,"admin");assertThrows(UnauthorizedException.class,()->ingestion.ingest("Bearer "+active.token,"k3",request(active,"bad3",null))); Fixture permitted=fixture(); Fixture other=fixture();assertThrows(ForbiddenException.class,()->ingestion.ingest("Bearer "+permitted.token,"k4",request(other,"bad4",null))); }
 @Test void rejectsSourceOutsideGrantInvalidContractAndIsIdempotentUnderConcurrency() throws Exception { Fixture f=fixture(); identities.createSource(f.org,f.project,"ci","admin"); IngestionService.Request noGrant=new IngestionService.Request("1.0",f.project,"ci","x", "test",Instant.now(),null,json.readTree("{}"),null,null);assertThrows(ForbiddenException.class,()->ingestion.ingest("Bearer "+f.token,"k",noGrant)); IngestionService.Request invalid=new IngestionService.Request("1.0",f.project,"git","y","test",Instant.now(),null,json.readTree("[]"),null,null);assertThrows(IllegalArgumentException.class,()->ingestion.ingest("Bearer "+f.token,"k",invalid)); String key="concurrent-"+UUID.randomUUID();IngestionService.Request req=request(f,"event-"+UUID.randomUUID(),null);ExecutorService pool=Executors.newFixedThreadPool(2);try{List<Future<IngestionService.Result>> results=pool.invokeAll(List.of(()->ingestion.ingest("Bearer "+f.token,key,req),()->ingestion.ingest("Bearer "+f.token,key,req)));long duplicates=0;for(Future<IngestionService.Result> result:results)if(result.get().duplicate())duplicates++;assertEquals(1,duplicates);}finally{pool.shutdownNow();}}
 private Fixture fixture(){Organization o=projects.createOrganization("org-"+UUID.randomUUID());Project p=projects.createProject(o.getId(),"project");DevelopmentActivity a=activities.create(o.getId(),p.getId(),"activity",null);identities.createSource(o.getId(),p.getId(),"git","admin");ServiceIdentity identity=identities.createIdentity(o.getId(),p.getId(),"collector","admin");identities.grant(o.getId(),p.getId(),identity.getId(),"git",ServiceScope.EVENTS_INGEST,"admin");ServiceIdentityService.IssuedCredential credential=identities.issue(o.getId(),p.getId(),identity.getId(),"admin");return new Fixture(o.getId(),p.getId(),a.getId(),identity.getId(),credential.credentialId(),credential.token());}
 private IngestionService.Request request(Fixture f,String event,UUID activity) throws Exception{return new IngestionService.Request("1.0",f.project,"git",event,"git_commit_created",Instant.now(),Instant.now(),json.readTree("{\"sha\":\"abc\"}"),activity==null?null:new IngestionService.Correlation(activity,.8),"https://example/repo");}
 record Fixture(UUID org,UUID project,UUID activity,UUID identity,UUID credential,String token){}
}
